delete_directory.Script:
target={{path}}
if [ -L "$target" ]; then printf '%s\n' 'Directory links are not supported.' >&2; exit 1; fi
if [ -e "$target" ]; then
  [ -d "$target" ] || { printf '%s\n' 'Target must be a directory.' >&2; exit 1; }
  rm -rf -- "$target" || exit 1
fi
[ ! -e "$target" ] && [ ! -L "$target" ] || { printf '%s\n' 'Directory is still present.' >&2; exit 1; }
printf 'absent: %s\n' "$target"

copy_file.Script:
source={{source}}
destination={{destination}}
source=${source%/}; destination=${destination%/}
[ ! -L "$source" ] && [ ! -L "$destination" ] || { printf '%s\n' 'Links are not supported.' >&2; exit 1; }
[ ! -e "$destination" ] || { printf '%s\n' 'Destination already exists.' >&2; exit 1; }
parent=$(dirname "$destination")
[ -d "$parent" ] || { printf '%s\n' 'Destination parent must exist.' >&2; exit 1; }
[ -f "$source" ] || { printf '%s\n' 'Source must be a regular file.' >&2; exit 1; }
(set -C; cat "$source" > "$destination") || exit 1
printf '%s\n' "$destination"

copy_directory.Script:
source={{source}}
destination={{destination}}
source=${source%/}; destination=${destination%/}
[ ! -L "$source" ] && [ ! -L "$destination" ] || { printf '%s\n' 'Links are not supported.' >&2; exit 1; }
[ ! -e "$destination" ] || { printf '%s\n' 'Destination already exists.' >&2; exit 1; }
parent=$(dirname "$destination")
[ -d "$parent" ] || { printf '%s\n' 'Destination parent must exist.' >&2; exit 1; }
[ -d "$source" ] || { printf '%s\n' 'Source must be a directory.' >&2; exit 1; }
ancestor=$parent
while :; do
  [ ! "$ancestor" -ef "$source" ] || { printf '%s\n' 'Destination must be outside the source directory.' >&2; exit 1; }
  next=$(dirname "$ancestor")
  [ "$next" != "$ancestor" ] || break
  ancestor=$next
done
unsupported=$(find "$source" ! -type f ! -type d -print) || exit 1
[ -z "$unsupported" ] || { printf '%s\n' 'Source contains links or unsupported entries.' >&2; exit 1; }
mkdir "$destination" || exit 1
cp -RP "$source/." "$destination" || exit 1
printf '%s\n' "$destination"

move_file.Script:
source={{source}}
destination={{destination}}
source=${source%/}; destination=${destination%/}
[ ! -L "$source" ] && [ ! -L "$destination" ] || { printf '%s\n' 'Links are not supported.' >&2; exit 1; }
[ ! -e "$destination" ] || { printf '%s\n' 'Destination already exists.' >&2; exit 1; }
parent=$(dirname "$destination")
[ -d "$parent" ] || { printf '%s\n' 'Destination parent must exist.' >&2; exit 1; }
[ -f "$source" ] || { printf '%s\n' 'Source must be a regular file.' >&2; exit 1; }
mv -n -- "$source" "$destination" || exit 1
[ ! -e "$source" ] && [ ! -L "$source" ] || { printf '%s\n' 'Move did not complete; source retained.' >&2; exit 1; }
printf '%s\n' "$destination"

